package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.text.InputType;import java.util.*;import java.util.concurrent.*;
/** Explicit online-map setup and bounded foreground area download. Partial cache survives cancellation. */
public final class OnlineMapActivity extends Activity {
 private LinearLayout root;private TextView status;private long project;private boolean running,disposed;private volatile boolean cancelled;private volatile OnlineTiles downloading;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 protected void onCreate(Bundle b){super.onCreate(b);project=getIntent().getLongExtra("project",-1);show("");}
 private void show(String message){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,18,18,18);root.setBackgroundColor(0xff232d1d);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TileSource s=OnlineMapSettings.source(this);
  text("Онлайн-карта и кеш",21);text(s.name+" · z"+s.minZoom+"–"+s.maxZoom+"\n"+s.attribution,14);status=text(message,14);text("В сеть передаются только запросы тайлов выбранной карты. Объекты, заметки и вложения остаются на устройстве.",13);
  CheckBox network=new CheckBox(this);network.setText("Загружать тайлы из интернета");network.setTextColor(-1);network.setChecked(OnlineMapSettings.network(this));root.addView(network);network.setOnCheckedChangeListener((v,on)->{if(running){network.post(()->network.setChecked(OnlineMapSettings.network(this)));return;}OnlineMapSettings.prefs(this).edit().putBoolean("network",on).commit();});
  button("Все исходные карты и наборы",()->catalog());button("OpenStreetMap — просмотр",()->{OnlineMapSettings.save(this,TileSource.osm(),project);show("Просмотр включён. Просмотренные тайлы сохраняются автоматически.");});button("Настроить XYZ-источник",()->configure());
  button("Показать выбранную карту",()->{OnlineMapSettings.use(this,project,true);finish();});button("Локальная подложка MBTiles",()->{OnlineMapSettings.use(this,project,false);finish();});
  button("Скачать область в кеш",()->region(false));if(OnlineMapSettings.prefs(this).contains("region_"+s.id))button("Продолжить предыдущую область",()->region(true));
  button("Экспорт кеша MBTiles",()->startActivity(new Intent(this,CacheExportActivity.class)));button("Объём кеша",()->stats());button("Очистить кеш источника",()->new AlertDialog.Builder(this).setMessage("Удалить все скачанные и просмотренные тайлы источника «"+s.name+"»? Кеш общих слоёв будет удалён и для других наборов. Проекты и импортированные MBTiles сохранятся.").setPositiveButton("Очистить",(d,w)->clear()).setNegativeButton("Отмена",null).show());
  button("К карте",()->finish());
 }
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(-1);t.setTextSize(size);t.setPadding(2,8,2,8);root.addView(t);return t;}
 private void button(String value,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(value);b.setTextColor(0xffffffff);android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(0xff374329);background.setCornerRadius(8);background.setStroke(1,0xff647750);b.setBackground(background);root.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!running)action.run();else status.setText("Дождитесь завершения или отмените загрузку");});}
 private EditText input(LinearLayout form,String title,String value,boolean numeric){TextView caption=new TextView(this);caption.setText(title);caption.setTextColor(0xff202020);form.addView(caption);EditText field=new EditText(this);field.setText(value);field.setTextColor(0xff202020);field.setBackgroundColor(-1);field.setSingleLine(true);field.setInputType(numeric?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);form.addView(field);return field;}
 private LinearLayout form(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(18,12,18,12);form.setBackgroundColor(0xfff2f5ed);return form;}
 private void configure(){TileSource s=OnlineMapSettings.source(this);if(s.layers!=null||!s.template.contains("{x}")||OnlineMapSettings.prefs(this).contains("catalog"))s=TileSource.osm();LinearLayout f=form();EditText name=input(f,"Название",s.name,false),url=input(f,"HTTPS-шаблон XYZ: {z}/{x}/{y}",s.template,false),attribution=input(f,"Подпись правообладателя",s.attribution,false),min=input(f,"Минимальный масштаб",Integer.toString(s.minZoom),true),max=input(f,"Максимальный масштаб",Integer.toString(s.maxZoom),true);CheckBox allowed=new CheckBox(this);allowed.setText("Источник разрешает скачивание областей");allowed.setTextColor(0xff202020);allowed.setChecked(s.downloads);f.addView(allowed);ScrollView scroll=new ScrollView(this);scroll.addView(f);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("XYZ-источник").setView(scroll).setPositiveButton("Сохранить",null).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{TileSource next=new TileSource(name.getText().toString().trim(),url.getText().toString().trim(),attribution.getText().toString().trim(),Integer.parseInt(min.getText().toString()),Integer.parseInt(max.getText().toString()),allowed.isChecked());OnlineMapSettings.save(this,next,project);dialog.dismiss();show("Источник сохранён; кеши разных адресов хранятся отдельно.");}catch(Exception e){url.setError(e.getMessage()==null?"Проверьте настройки":e.getMessage());}}));dialog.show();}
 private void region(boolean previous){TileSource s=OnlineMapSettings.source(this);if(!s.downloads){new AlertDialog.Builder(this).setMessage("Этот источник разрешает только просмотр и кеш просмотренного. Для скачивания области настройте XYZ-источник, который разрешает такую загрузку.").setPositiveButton("Настроить",(d,w)->configure()).setNegativeButton("Закрыть",null).show();return;}if(!OnlineMapSettings.network(this)){status.setText("Включите загрузку тайлов из интернета");return;}
  double[] bounds=getIntent().getDoubleArrayExtra("bounds");if(bounds==null||bounds.length!=4)bounds=new double[]{-1,-1,1,1};int z=(int)getIntent().getDoubleExtra("zoom",2);String[] values={number(bounds[0]),number(bounds[1]),number(bounds[2]),number(bounds[3]),Integer.toString(Math.max(s.minZoom,Math.min(s.maxZoom,z))),Integer.toString(Math.max(s.minZoom,Math.min(s.maxZoom,z+2)))};
  if(previous){String[] saved=OnlineMapSettings.prefs(this).getString("region_"+s.id,"").split(";");if(saved.length==6)values=saved;}
  LinearLayout f=form();String[] names={"Запад: долгота","Юг: широта","Восток: долгота","Север: широта","От масштаба","До масштаба"};EditText[] fields=new EditText[6];for(int i=0;i<6;i++)fields[i]=input(f,names[i],values[i],true);TextView hint=new TextView(this);hint.setText("Начальные границы — видимая область карты. Запад > востока означает пересечение 180°. До 20 000 тайлов, кеш источника до 256 МиБ. Загрузка идёт, пока открыт этот экран; отмена сохраняет полученное.");hint.setTextColor(0xff202020);f.addView(hint);ScrollView scroll=new ScrollView(this);scroll.addView(f);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Область для скачивания").setView(scroll).setPositiveButton("Рассчитать",null).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{String[] chosen=new String[6];for(int i=0;i<6;i++)chosen[i]=fields[i].getText().toString().trim().replace(',','.');int min=Integer.parseInt(chosen[4]),max=Integer.parseInt(chosen[5]);if(min<s.minZoom||max>s.maxZoom)throw new IllegalArgumentException("Масштабы источника: "+s.minZoom+"–"+s.maxZoom);TileDownloadPlan region=new TileDownloadPlan(s,Double.parseDouble(chosen[0]),Double.parseDouble(chosen[1]),Double.parseDouble(chosen[2]),Double.parseDouble(chosen[3]),min,max);dialog.dismiss();new AlertDialog.Builder(this).setMessage("Область: "+region.count+" тайлов. Уже сохранённые будут пропущены. Максимум новых данных — до "+Math.min(256,region.count)+" МиБ. Скачать?").setPositiveButton("Скачать",(a,w)->{OnlineMapSettings.prefs(this).edit().putString("region_"+s.id,join(chosen)).commit();download(s,region);}).setNegativeButton("Отмена",null).show();}catch(Exception e){fields[0].setError(e.getMessage());}}));dialog.show();
 }
 private static String number(double n){return String.format(Locale.US,"%.8f",n);}private static String join(String[] v){StringBuilder b=new StringBuilder();for(String s:v){if(b.length()>0)b.append(';');b.append(s);}return b.toString();}
 private void download(TileSource s,TileDownloadPlan region){running=true;cancelled=false;root.removeAllViews();text("Скачивание: "+s.name,20);status=text("Подготовка…",15);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax((int)region.count);root.addView(bar);Button cancel=new Button(this);cancel.setText("Отменить загрузку");cancel.setTextColor(0xffffffff);cancel.setBackgroundColor(0xff374329);root.addView(cancel);cancel.setOnClickListener(v->cancel());
  worker.execute(()->{int done=0;String failure=null;try{for(int layer=0;layer<region.sources.length&&!cancelled&&!disposed;layer++){try(OnlineTiles cache=new OnlineTiles(this,region.sources[layer])){downloading=cache;for(int[] tile:region.regions[layer]){if(cancelled||disposed)break;cache.download(tile[0],tile[1],tile[2]);final int progress=++done;if(progress==1||progress%5==0||progress==region.count)runOnUiThread(()->{if(!disposed){bar.setProgress(progress);status.setText("Сохранено: "+progress+" / "+region.count);}});Thread.sleep(200);}}}}catch(Exception e){if(!cancelled)failure=e.getMessage();}finally{downloading=null;}final int completed=done;final String error=failure;runOnUiThread(()->{if(disposed)return;running=false;show(error!=null?"Загрузка остановлена: "+error+". Полученное сохранено; можно продолжить.":(cancelled?"Отменено. ":"Готово. ")+"В кеше: "+completed+" из "+region.count+" тайлов этой области.");});});
 }
 private void stats(){running=true;worker.execute(()->{String message;try{long[] totals=new long[3];for(TileSource leaf:OnlineMapSettings.source(this).leafs())try(OnlineTiles cache=new OnlineTiles(this,leaf)){long[] n=cache.stats();for(int i=0;i<3;i++)totals[i]+=n[i];}message=String.format(Locale.US,"Кеш: %d тайлов · %.2f МиБ · для областей: %d",totals[0],totals[1]/1048576.0,totals[2]);}catch(Exception e){message="Не удалось прочитать кеш: "+e.getMessage();}final String text=message;runOnUiThread(()->{running=false;if(!disposed)status.setText(text);});});}
 private void clear(){running=true;worker.execute(()->{String message;try{for(TileSource leaf:OnlineMapSettings.source(this).leafs())try(OnlineTiles cache=new OnlineTiles(this,leaf)){cache.clear();}message="Кеш источника очищен";}catch(Exception e){message="Не удалось очистить кеш: "+e.getMessage();}final String text=message;runOnUiThread(()->{running=false;if(!disposed)status.setText(text);});});}
 private void catalog(){startActivityForResult(new Intent(this,MapCatalogActivity.class).putExtra("project",project),4501);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==4501&&result==RESULT_OK){show("Карта выбрана. Для открытия нажмите «Показать выбранную карту».");if(data!=null&&data.getIntExtra(MapCatalogActivity.RESULT_ACTION,0)==MapCatalogActivity.ACTION_EXPORT)startActivity(new Intent(this,CacheExportActivity.class));}}
 private void cancel(){cancelled=true;OnlineTiles cache=downloading;if(cache!=null)cache.cancel();if(status!=null)status.setText("Отмена… Полученные тайлы сохраняются");}
 public void onBackPressed(){if(running)cancel();else super.onBackPressed();}
 protected void onStop(){if(running)cancel();super.onStop();}protected void onDestroy(){disposed=true;cancel();worker.shutdown();super.onDestroy();}
}
